\pset tuples_only on
set role authenticated; set request.uid='00000000-0000-0000-0000-0000000000a1';
-- factura de $100 a crédito, con mora
select 'crea', jsonb_array_length(public.sync(0,'[{"c":"facturas","id":"fm","u":7000,"d":0,"data":{"id":"fm","num":"F-000009","total":100,"subtotal":100,"tipo":"CREDITO","estado":"PENDIENTE","mora":2,"cuotas":1,"fechas":["2026-11-10"],"items":[],"abonos":[]}}]')->'recs') > 0;
-- primer abono: $60 de los cuales $10 son mora
select 'abono1 (60, mora 10)', (select r->'data'->>'estado' from jsonb_array_elements(public.sync(0,'[{"c":"facturas","id":"fm","u":7100,"d":0,"data":{"id":"fm","num":"F-000009","total":100,"subtotal":100,"tipo":"CREDITO","estado":"PENDIENTE","mora":2,"cuotas":1,"fechas":["2026-11-10"],"items":[],"abonos":[{"id":"a1","fecha":"2026-11-13T10:00:00Z","monto":60,"mora":10,"metodo":"Efectivo"}]}}]')->'recs') r where r->>'id'='fm');
-- segundo abono $40: suma de montos = 100 (con la fórmula vieja saldría PAGADA, pero el capital es 90)
select 'abono2 (40) -> debe seguir PENDIENTE', (select r->'data'->>'estado' from jsonb_array_elements(public.sync(0,'[{"c":"facturas","id":"fm","u":7200,"d":0,"data":{"id":"fm","num":"F-000009","total":100,"subtotal":100,"tipo":"CREDITO","estado":"PENDIENTE","mora":2,"cuotas":1,"fechas":["2026-11-10"],"items":[],"abonos":[{"id":"a1","fecha":"2026-11-13T10:00:00Z","monto":60,"mora":10,"metodo":"Efectivo"},{"id":"a2","fecha":"2026-11-14T10:00:00Z","monto":40,"mora":0,"metodo":"Efectivo"}]}}]')->'recs') r where r->>'id'='fm');
-- tercer abono $10 de capital: ahora sí PAGADA y conserva fechas/mora
select 'abono3 (10) -> PAGADA y conserva mora/fechas', (select r->'data'->>'estado' || ' mora=' || (r->'data'->>'mora') || ' fechas=' || (r->'data'->'fechas')::text || ' abonos=' || jsonb_array_length(r->'data'->'abonos') || ' mora_a1=' || (r->'data'->'abonos'->0->>'mora') from jsonb_array_elements(public.sync(0,'[{"c":"facturas","id":"fm","u":7300,"d":0,"data":{"id":"fm","num":"F-000009","total":100,"subtotal":100,"tipo":"CREDITO","estado":"PENDIENTE","mora":2,"cuotas":1,"fechas":["2026-11-10"],"items":[],"abonos":[{"id":"a1","fecha":"2026-11-13T10:00:00Z","monto":60,"mora":10,"metodo":"Efectivo"},{"id":"a2","fecha":"2026-11-14T10:00:00Z","monto":40,"mora":0,"metodo":"Efectivo"},{"id":"a3","fecha":"2026-11-15T10:00:00Z","monto":10,"mora":0,"metodo":"Efectivo"}]}}]')->'recs') r where r->>'id'='fm');
-- dos equipos: un equipo con abono viejo (u menor) aporta un abono distinto y el servidor une todo
select 'union de abonos entre equipos', (select jsonb_array_length(r->'data'->'abonos') || ' abonos, ' || (r->'data'->>'estado') from jsonb_array_elements(public.sync(0,'[{"c":"facturas","id":"fm","u":7050,"d":0,"data":{"id":"fm","num":"F-000009","total":100,"tipo":"CREDITO","estado":"PENDIENTE","mora":2,"items":[],"abonos":[{"id":"a9","fecha":"2026-11-12T10:00:00Z","monto":5,"mora":0,"metodo":"Efectivo"}]}}]')->'recs') r where r->>'id'='fm');
